<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class CarrierController extends Controller{
 public function index(Request$r):JsonResponse{$this->permit($r,'logistics.view');$f=$r->validate(['search'=>['nullable','string','max:150'],'type'=>['nullable','string','max:80'],'status'=>['nullable','string','max:30'],'sort'=>['nullable',Rule::in(['name','partner_type','status','created_at','updated_at'])],'direction'=>['nullable',Rule::in(['asc','desc'])],'per_page'=>['nullable','integer','between:1,100']]);$q=$this->query($f);$total=(clone$q)->count();$rows=(clone$q)->leftJoinSub(DB::table('shipments')->whereNull('deleted_at')->selectRaw('logistics_partner_id,COUNT(*) assigned,SUM(CASE WHEN status="delivered" THEN 1 ELSE 0 END) delivered,SUM(CASE WHEN status="failed" THEN 1 ELSE 0 END) failed')->groupBy('logistics_partner_id'),'stats','stats.logistics_partner_id','=','logistics_partners.id')->select(['logistics_partners.*',DB::raw('COALESCE(stats.assigned,0) assigned_shipments'),DB::raw('COALESCE(stats.delivered,0) delivered_shipments'),DB::raw('COALESCE(stats.failed,0) failed_shipments')])->orderBy('logistics_partners.'.($f['sort']??'created_at'),$f['direction']??'desc')->paginate($f['per_page']??25);$types=(clone$q)->groupBy('partner_type')->selectRaw('partner_type type,COUNT(*) count')->get();$assigned=DB::table('shipments')->whereNull('deleted_at')->count();$delivered=DB::table('shipments')->whereNull('deleted_at')->where('status','delivered')->count();return response()->json(['data'=>['updated_at'=>now()->toIso8601String(),'metrics'=>['totalCarriers'=>$total,'activeCarriers'=>(clone$q)->where('status','active')->count(),'approvedPartners'=>(clone$q)->where('status','active')->count(),'limitedServiceCarriers'=>(clone$q)->where('status','limited_service')->count(),'suspendedCarriers'=>(clone$q)->where('status','suspended')->count(),'activeShippingServices'=>DB::table('logistics_partner_services')->whereNull('deleted_at')->where('status','active')->count(),'shipmentsAssignedThisPeriod'=>$assigned,'pickupSlaBreaches'=>0,'deliverySlaBreaches'=>DB::table('shipments')->whereNull('deleted_at')->whereNotIn('status',['delivered','cancelled'])->whereDate('estimated_delivery_date','<',today())->count(),'trackingExceptions'=>0,'carrierClaimsOpen'=>0,'codReconciliationExceptions'=>0,'lastSynced'=>now()->toIso8601String()],'type_distribution'=>$types,'network'=>['healthScore'=>null,'healthLabel'=>'Unknown','healthDescription'=>'No carrier health telemetry configured','healthTrend'=>'—','alerts'=>[],'carrierSummary'=>['totalCarriers'=>$total,'active'=>(clone$q)->where('status','active')->count(),'limited'=>(clone$q)->where('status','limited_service')->count(),'suspended'=>(clone$q)->where('status','suspended')->count()],'capacitySummary'=>['utilizationPercentage'=>null,'totalCapacity'=>'—','usedCapacity'=>'—','remainingCapacity'=>'—'],'shipmentSummary'=>['assigned'=>$assigned,'delivered'=>$delivered,'inTransit'=>DB::table('shipments')->whereNull('deleted_at')->where('status','in_transit')->count(),'failed'=>DB::table('shipments')->whereNull('deleted_at')->where('status','failed')->count()]],'carriers'=>$rows]]);}
 public function show(Request$r,string$c):JsonResponse{$this->permit($r,'logistics.view');$row=$this->find($c);abort_unless($row,404);return response()->json(['data'=>['carrier'=>$row,'services'=>DB::table('logistics_partner_services')->whereNull('deleted_at')->where('logistics_partner_id',$row->id)->get(),'shipments'=>DB::table('shipments')->whereNull('deleted_at')->where('logistics_partner_id',$row->id)->latest()->paginate(25)]]);}
 public function store(Request$r):JsonResponse{$this->permit($r,'logistics.create');return$this->save($r);}
 public function update(Request$r,string$c):JsonResponse{$this->permit($r,'logistics.update');$row=$this->find($c);abort_unless($row,404);return$this->save($r,$row->id);}
 public function status(Request$r,string$c):JsonResponse{$this->permit($r,'logistics.update');$row=$this->find($c);abort_unless($row,404);$d=$r->validate(['status'=>['required',Rule::in(['active','limited_service','suspended','on_hold','offline'])],'reason'=>['nullable','string','max:2000']]);if($d['status']==='suspended')abort_if(DB::table('shipments')->whereNull('deleted_at')->where('logistics_partner_id',$row->id)->whereNotIn('status',['delivered','returned','cancelled'])->exists(),422,'Carrier has active shipments and cannot be suspended.');DB::transaction(function()use($r,$row,$d){DB::table('logistics_partners')->where('id',$row->id)->update(['status'=>$d['status'],'updated_at'=>now()]);activity('admin')->causedBy($r->user())->withProperties(['carrier_id'=>$row->id,'from'=>$row->status,'to'=>$d['status'],'reason'=>$d['reason']??null])->log('carrier.status_changed');});return response()->json(['data'=>['carrier'=>$this->find((string)$row->id)]]);}
 private function save(Request$r,?int$id=null):JsonResponse{$d=$r->validate(['name'=>[$id?'sometimes':'required','string','max:150',Rule::unique('logistics_partners','name')->ignore($id)],'partner_type'=>['nullable','string','max:80'],'contact_name'=>['nullable','string','max:150'],'email'=>['nullable','email','max:150'],'phone'=>['nullable','string','max:50'],'website'=>['nullable','url','max:255'],'address'=>['nullable','string','max:2000'],'status'=>['sometimes',Rule::in(['active','limited_service','suspended','on_hold','offline'])]]);$row=DB::transaction(function()use($r,$d,$id){$d['updated_at']=now();if($id)DB::table('logistics_partners')->where('id',$id)->update($d);else{$d['uuid']=(string)Str::uuid();$d['slug']=Str::slug($d['name']).'-'.Str::lower(Str::random(5));$d['created_at']=now();$id=DB::table('logistics_partners')->insertGetId($d);}activity('admin')->causedBy($r->user())->withProperties(['carrier_id'=>$id,'fields'=>array_keys($d)])->log($id?'carrier.updated':'carrier.created');return DB::table('logistics_partners')->find($id);});return response()->json(['data'=>['carrier'=>$row]],$id?200:201);}
 private function query(array$f){$q=DB::table('logistics_partners')->whereNull('deleted_at');if($v=$f['type']??null)$q->where('partner_type',$v);if($v=$f['status']??null)$q->where('status',$v);if($v=$f['search']??null)$q->where(fn($x)=>$x->where('name','like','%'.$v.'%')->orWhere('slug','like','%'.$v.'%')->orWhere('contact_name','like','%'.$v.'%'));return$q;}
 private function find(string$c){return DB::table('logistics_partners')->whereNull('deleted_at')->where(function($q)use($c){$q->where('uuid',$c)->orWhere('slug',$c);if(ctype_digit($c))$q->orWhere('id',(int)$c);})->first();}private function permit(Request$r,string$p):void{abort_unless($r->user()->hasPermission($p),403);}
}
